from pathlib import Path
import json,hashlib,csv
import numpy as np
OUT=Path(__file__).resolve().parent;ROOT=Path('/home/isee/Catch/catch_it_copy')
expected=[f'{m}_{o}_range{s}' for m,objects in [('bounce',['original','tennis_ball']),('roll',['apple','lemon'])] for o in objects for s in (1.,.5,0.)]+['bounce_original_spin0','bounce_original_nearer','bounce_original_threeball']
results=[];allrows={}
for name in expected:
 folder=OUT/name;s=json.loads((folder/'summary.json').read_text());rows=[json.loads(x) for x in (folder/'episodes.jsonl').read_text().splitlines()];allrows[name]=rows
 assert s['completed'] and len(rows)==s['episodes'] and sum(r['success'] for r in rows)==s['successes']
 assert len({(r['slot'],r['episode']) for r in rows})==len(rows)
 assert all(sum(r['slot']==slot for r in rows)==s['episodes']//10 for slot in range(10))
 assert hashlib.sha256(Path(s['checkpoint']).read_bytes()).hexdigest()==s['checkpoint_sha256']
 r={k:s[k] for k in ('name','motion','object','episodes','successes','success_rate','wilson_95_interval','reasons','checkpoint_sha256')}
 if s['motion']=='bounce':
  fail=[x for x in rows if not x['success']];p=[x['bounce_diagnostics']['bounce_grasp_probe'] for x in fail];c=sum(x['contact_ticks'] for x in p)
  r['failure_diagnostics']=dict(failures=len(fail),had_contact=sum(x['first_contact'] is not None for x in p),never_two_contact_groups=sum(x['max_groups']<2 for x in p),never_low_speed_contact=sum(x['contact_gates'].get('speed',0)==0 for x in p),never_valid_hold=sum(x['gates'].get('valid',0)==0 for x in p),contact_tick_gate_fractions={k:sum(x['contact_gates'].get(k,0) for x in p)/max(1,c) for k in ('capture','groups','span','speed','off_ground','joint','valid')})
 results.append(r)
# Check same per-slot/per-episode launch seeds and intended intervention for all comparisons.
def keyed(name):return {(r['slot'],r['episode']):r for r in allrows[name]}
for m,objects in [('bounce',['original','tennis_ball']),('roll',['apple','lemon'])]:
 for o in objects:
  ref=keyed(f'{m}_{o}_range1.0')
  for scale in (.5,0.):
   for k,r in keyed(f'{m}_{o}_range{scale}').items():
    a=ref[k];assert r['episode_seed']==a['episode_seed']
    if m=='bounce':np.testing.assert_allclose(r['initial']['qpos'],a['initial']['qpos'],atol=1e-12);np.testing.assert_allclose(r['initial']['qvel'][:3],a['initial']['qvel'][:3],atol=1e-12)
    for field in ('size_scale','mass_scale','friction_scale','rolling_scale','damping_scale'):
     np.testing.assert_allclose(r['physics']['randomization'][field],1+(a['physics']['randomization'][field]-1)*scale,atol=1e-12)
ref=keyed('bounce_original_range1.0')
for name in ('bounce_original_spin0','bounce_original_nearer','bounce_original_threeball'):
 for k,r in keyed(name).items():
  a=ref[k];assert r['episode_seed']==a['episode_seed'];assert r['physics']['randomization']==a['physics']['randomization']
  if name.endswith('threeball'):
   np.testing.assert_array_equal(r['initial']['qpos'],a['initial']['qpos']);np.testing.assert_array_equal(r['initial']['qvel'],a['initial']['qvel'])
  if name.endswith('spin0'):
   np.testing.assert_array_equal(r['initial']['qpos'],a['initial']['qpos']);np.testing.assert_allclose(r['initial']['qvel'][:3],a['initial']['qvel'][:3]);np.testing.assert_allclose(r['initial']['qvel'][3:5],0)
  if name.endswith('nearer'):
   np.testing.assert_allclose(np.asarray(r['initial']['qpos'])[[0,2,3,4,5,6]],np.asarray(a['initial']['qpos'])[[0,2,3,4,5,6]])
   np.testing.assert_array_equal(r['initial']['qvel'],a['initial']['qvel']);np.testing.assert_allclose(r['initial']['qpos'][1],1.6+(a['initial']['qpos'][1]-1.6)*.5)
for name,digest in json.loads((OUT/'source_hashes.json').read_text()).items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest,name
(OUT/'summary.json').write_text(json.dumps(results,indent=2))
(OUT/'VALIDATION.json').write_text(json.dumps(dict(cases=len(results),episodes=sum(r['episodes'] for r in results),exact_quotas=True,unique_episode_ids=True,same_launch_seeds=True,interventions_verified=True,checkpoint_hashes_verified=True,production_source_hashes_unchanged=True,notes='Same launch seeds/states do not guarantee identical subsequent observation/control noise: synchronous environments share the historical global NumPy RNG. Physical draws are clustered by ten environment instances; these are diagnostic samples, not definitive significance tests.'),indent=2))
lines=['# Roll/Bounce Catch diagnosis, 2026-11-11','','Only analysis scripts and evaluation artifacts were added; production rewards, launch defaults, training and physics files are unchanged.','','## Controlled diagnostic evaluation','','10 physical instances per case; 60 episodes per Bounce case, 40 per Roll case; deterministic policy, explicit launch seeds. Range 1 is current DR, 0.5 scales each relative deviation by half, 0 uses nominal physics with the same launch sampling. All failures are retained.','','|Case|Successes|Rate|Wilson 95% CI|','|---|---:|---:|---|']
for r in results:lines.append(f"|{r['name']}|{r['successes']}/{r['episodes']}|{r['success_rate']:.1%}|{r['wilson_95_interval'][0]:.1%}–{r['wilson_95_interval'][1]:.1%}|")
lines+=['','## Interpretation and limits','','- Same-model inference ablations diagnose sensitivity; they do not prove that retraining with a smaller range will improve performance. Small samples and shared physical instances limit precision.','- Same launch seeds/states are verified. Subsequent noise is not strictly paired because historical synchronous environments share a global NumPy RNG and episode lengths/resets diverge.','- Original six-ball policy: inspect contact_tick_gate_fractions and never_valid_hold in summary.json. Contact alone is not a grasp. Most existing 200-episode failures had hand contact, but could not maintain capture/contact geometry/low relative speed together.','- Original legacy route uses a different launch sampler from new benchmark balls: larger lateral/heading spread and forward-speed-dependent spin. New balls have material-aware rebound-apex launches and zero angular velocity. This is a distribution difference, not by itself a proven causal explanation.','- spin0 removes X/Y speed-dependent spin only; the original Z spin sample [-3,3] rad/s remains. This intervention is diagnostic and is not a changed default.','- nearer changes only the initial Y-distance range from [1.6,2.0] to [1.6,1.8] m. It is not a benchmark improvement unless the changed launch distribution is explicitly reported.','- The old three-ball and current six-ball checkpoints are evaluated under identical current original-ball physics and launch states. Differences establish checkpoint capability differences, but cannot separate all historical training-recipe causes without a matched training experiment.','','## Physical randomization versus Throw','','Current relative ranges: dimensions/radius ±5%; mass ±10%; floor/table sliding friction ±15%; Roll rolling length ±20%; Bounce contact damping ratio ±10%. Inertia follows mass times size squared. The damping ratio is not a restitution coefficient.','Throw sphere radius is 0.035–0.045 m (±12.5% about 0.04 m); free-joint damping is 0.005–0.02, unlike contact damping. Throw mass configuration says 0.035–0.075 kg but its implementation calls uniform(low,low), so actual sampled mass is fixed at 0.035 kg. It does not randomize the same surface contact parameters as this DR version.','All these physics draws occur at environment creation, not every episode. Default multi-target scripts use 28 Roll / 24 Bounce environments, ordinarily four physical profiles per target. Actual remote run overrides require its saved training config/provenance to verify.','','## Recommended next experiments','','1. Preserve current model/physics/reward snapshots; use validation success, not training best reward alone, to select checkpoints. Current Bounce best is better than last; last did not improve with more steps.','2. Fine-tune a strong Catch policy into the multi-target task rather than necessarily reinitializing Catch from Track. Preserve old-target skills with old-policy distillation or balanced nominal/DR coverage. Use smaller joint-update learning rates and compare Track learning-rate reduction against the current equal-rate recipe.','3. Increase physics-profile coverage: per-reset resampling where safe, or a larger prevalidated profile pool. Include held-out profile/launch seeds for validation.','4. Use half-range as an optional training curriculum, then expand to current ranges; keep final evaluation distribution unchanged and report both nominal and randomized performance. Do not declare smaller ranges necessary based on this small inference ablation.','5. Improve capture-to-hold learning: review existing capture, contact coverage, relative-speed and holding-progress shaping before adding more rewards. Keep real-contact/off-ground success requirements. Consider observable size/aspect features or history/recurrent inputs; present policy lacks explicit object size, material and angular velocity.','6. Keep Roll held-at-end and stable-hold metrics separate. Fixed Roll 261.94 has 62.9% region-retention success in the existing test but 0% ever-stable hold; a higher primary rate alone does not demonstrate better grip quality.','','Raw per-episode diagnostics, parameter draws, commands/scripts and source/checkpoint hashes are retained in this directory.']
(OUT/'REPORT.md').write_text('\n'.join(lines)+'\n');(OUT/'COMPLETE').write_text(f"{len(results)} cases; {sum(r['episodes'] for r in results)} completed episodes; validation passed\n")
print((OUT/'REPORT.md').read_text())
